// Use proven syn visitor pattern from split-decls-rs/rustmacrodoc
pub struct SymbolVisitor {
    pub symbols: Vec<Symbol>,
    current_file: String,
    current_crate: String,
}

impl SymbolVisitor {
    pub fn new(crate_name: String) -> Self {
        Self {
            symbols: Vec::new(),
            current_file: String::new(),
            current_crate: crate_name,
        }
    }
    
    pub fn set_file(&mut self, file_path: String) {
        self.current_file = file_path;
    }
    
    pub fn visit_file(&mut self, file: &syn::File) {
        // First pass: collect all use statements at file level
        let mut use_mappings = HashMap::new();
        for item in &file.items {
            if let syn::Item::Use(use_item) = item {
                self.extract_use_mappings_to_map(&use_item.tree, Vec::new(), &mut use_mappings);
            }
        }
        
        // Second pass: visit all items with use mappings available
        for item in &file.items {
            match item {
                syn::Item::Fn(func) => {
                    let body_analysis = analyze_function_body_ast(&func.block);
                    let mut deps = extract_function_dependencies_ast(func);
                    
                    // Apply use mappings to resolve short names
                    deps = deps.into_iter().map(|dep| {
                        // Handle method calls like "Instant::now" -> extract "Instant"
                        let base_type = if dep.contains("::") {
                            dep.split("::").next().unwrap_or(&dep)
                        } else {
                            &dep
                        };
                        
                        if let Some(full_path) = use_mappings.get(base_type) {
                            // Reconstruct with full path: "std::time::Instant::now"
                            if dep.contains("::") {
                                let method = dep.split("::").skip(1).collect::<Vec<_>>().join("::");
                                format!("{}::{}", full_path, method)
                            } else {
                                full_path.clone()
                            }
                        } else {
                            dep
                        }
                    }).collect();
                    
                    let symbol = Symbol {
                        name: func.sig.ident.to_string(),
                        symbol_type: body_analysis,
                        source_file: self.current_file.clone(),
                        crate_name: self.current_crate.clone(),
                        dependencies: deps,
                    };
                    self.symbols.push(symbol);
                }
                _ => {
                    syn::visit::visit_item(self, item);
                }
            }
        }
    }
    
    fn extract_use_mappings_to_map(&self, tree: &syn::UseTree, prefix: Vec<String>, mappings: &mut HashMap<String, String>) {
        match tree {
            syn::UseTree::Path(path) => {
                let mut new_prefix = prefix;
                new_prefix.push(path.ident.to_string());
                self.extract_use_mappings_to_map(&path.tree, new_prefix, mappings);
            }
            syn::UseTree::Name(name) => {
                let mut full_path = prefix;
                full_path.push(name.ident.to_string());
                let short_name = name.ident.to_string();
                mappings.insert(short_name, full_path.join("::"));
            }
            syn::UseTree::Group(group) => {
                for item in &group.items {
                    self.extract_use_mappings_to_map(item, prefix.clone(), mappings);
                }
            }
            _ => {}
        }
    }
}

impl<'ast> Visit<'ast> for SymbolVisitor {
    fn visit_item_fn(&mut self, node: &'ast syn::ItemFn) {
        let body_analysis = analyze_function_body_ast(&node.block);
        let deps = extract_function_dependencies_ast(node);
        
        // Handle generic functions
        let generics_info = if node.sig.generics.params.is_empty() {
            "".to_string()
        } else {
            format!("<{}>", node.sig.generics.params.len())
        };
        
        self.symbols.push(Symbol {
            name: node.sig.ident.to_string(),
            symbol_type: format!("fn{}{}", generics_info, body_analysis),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_fn(self, node);
    }
    
    fn visit_item_struct(&mut self, node: &'ast syn::ItemStruct) {
        let deps = extract_struct_dependencies(node);
        self.symbols.push(Symbol {
            name: node.ident.to_string(),
            symbol_type: "struct".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_struct(self, node);
    }
    
    fn visit_item_enum(&mut self, node: &'ast syn::ItemEnum) {
        let deps = extract_enum_dependencies(node);
        self.symbols.push(Symbol {
            name: node.ident.to_string(),
            symbol_type: "enum".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_enum(self, node);
    }
    
    fn visit_item_trait(&mut self, node: &'ast syn::ItemTrait) {
        let deps = extract_trait_dependencies(node);
        self.symbols.push(Symbol {
            name: node.ident.to_string(),
            symbol_type: "trait".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_trait(self, node);
    }
    
    fn visit_item_impl(&mut self, node: &'ast syn::ItemImpl) {
        let deps = extract_impl_dependencies(node);
        let impl_name = format!("impl_{}", self.symbols.len());
        self.symbols.push(Symbol {
            name: impl_name,
            symbol_type: "impl".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_impl(self, node);
    }
    
    fn visit_item_const(&mut self, node: &'ast syn::ItemConst) {
        let deps = extract_const_dependencies(node);
        self.symbols.push(Symbol {
            name: node.ident.to_string(),
            symbol_type: "const".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_const(self, node);
    }
    
    fn visit_item_static(&mut self, node: &'ast syn::ItemStatic) {
        let deps = extract_static_dependencies(node);
        self.symbols.push(Symbol {
            name: node.ident.to_string(),
            symbol_type: "static".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_static(self, node);
    }
    
    fn visit_item_use(&mut self, node: &'ast syn::ItemUse) {
        let use_path = format!("{}", node.tree.to_token_stream());
        self.symbols.push(Symbol {
            name: format!("use_{}", use_path.replace(" ", "_").replace("::", "_")),
            symbol_type: format!("use[{}]", use_path),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: vec![use_path],
        });
        syn::visit::visit_item_use(self, node);
    }
    
    fn visit_item_macro(&mut self, node: &'ast syn::ItemMacro) {
        let macro_name = if let Some(ident) = &node.ident {
            ident.to_string()
        } else {
            format!("macro_{}", self.symbols.len())
        };
        
        self.symbols.push(Symbol {
            name: macro_name,
            symbol_type: "macro".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: vec![],
        });
        syn::visit::visit_item_macro(self, node);
    }
    
    fn visit_macro(&mut self, node: &'ast syn::Macro) {
        let macro_path = node.path.segments.iter()
            .map(|seg| seg.ident.to_string())
            .collect::<Vec<_>>()
            .join("::");
        
        self.symbols.push(Symbol {
            name: format!("macro_call_{}", macro_path),
            symbol_type: "macro_call".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: vec![macro_path],
        });
        syn::visit::visit_macro(self, node);
    }
    
    fn visit_item(&mut self, node: &'ast syn::Item) {
        // Catch-all for any item types we haven't handled specifically
        match node {
            syn::Item::Fn(_) => {}, // Already handled
            syn::Item::Struct(_) => {}, // Already handled  
            syn::Item::Enum(_) => {}, // Already handled
            syn::Item::Trait(_) => {}, // Already handled
            syn::Item::Impl(_) => {}, // Already handled
            syn::Item::Const(_) => {}, // Already handled
            syn::Item::Static(_) => {}, // Already handled
            syn::Item::Type(_) => {}, // Already handled
            syn::Item::Use(_) => {}, // Already handled
            syn::Item::Macro(_) => {}, // Already handled
            _ => {
                // Unhandled item type - capture it
                let item_name = format!("unhandled_item_{}", self.symbols.len());
                let item_type = format!("unhandled_{:?}", std::mem::discriminant(node));
                
                self.symbols.push(Symbol {
                    name: item_name,
                    symbol_type: item_type,
                    source_file: self.current_file.clone(),
                    crate_name: self.current_crate.clone(),
                    dependencies: vec![],
                });
            }
        }
        syn::visit::visit_item(self, node);
    }
    
    fn visit_item_type(&mut self, node: &'ast syn::ItemType) {
        let deps = extract_type_dependencies(node);
        self.symbols.push(Symbol {
            name: node.ident.to_string(),
            symbol_type: "type".to_string(),
            source_file: self.current_file.clone(),
            crate_name: self.current_crate.clone(),
            dependencies: deps,
        });
        syn::visit::visit_item_type(self, node);
    }
}

// Use proven file parsing pattern from simple-split
pub fn extract_all_symbols_from_file_fast(file_path: &str, crate_name: &str) -> Result<Vec<Symbol>> {
    let content = std::fs::read_to_string(file_path)?;
    
    // Use exact same parsing as simple-split
    if let Ok(parsed) = syn::parse_file(&content) {
        let mut visitor = SymbolVisitor {
            symbols: Vec::new(),
            current_file: file_path.to_string(),
            current_crate: crate_name.to_string(),
        };
        
        // Enable all features for comprehensive parsing
        visitor.visit_file(&parsed);
        
        // Also capture any top-level items we might have missed
        for (i, item) in parsed.items.iter().enumerate() {
            // Check for feature-gated items
            let has_stable_attr = match item {
                syn::Item::Fn(f) => f.attrs.iter().any(|attr| {
                    attr.path().is_ident("stable") || 
                    attr.path().is_ident("unstable") ||
                    attr.path().is_ident("cfg")
                }),
                syn::Item::Struct(s) => s.attrs.iter().any(|attr| {
                    attr.path().is_ident("stable") || 
                    attr.path().is_ident("unstable") ||
                    attr.path().is_ident("cfg")
                }),
                _ => false,
            };
            
            match item {
                syn::Item::Fn(func) => {
                    // Check if we captured this function
                    let func_name = func.sig.ident.to_string();
                    if !visitor.symbols.iter().any(|s| s.name == func_name) {
                        // This might be a feature-gated function we missed
                        let symbol_type = if has_stable_attr {
                            "feature_gated_fn".to_string()
                        } else {
                            "missed_function".to_string()
                        };
                        
                        visitor.symbols.push(Symbol {
                            name: func_name,
                            symbol_type,
                            source_file: file_path.to_string(),
                            crate_name: crate_name.to_string(),
                            dependencies: vec![],
                        });
                    }
                },
                _ => {
                    // Capture any other items we might have missed
                    let symbol_type = if has_stable_attr {
                        format!("feature_gated_{:?}", std::mem::discriminant(item))
                    } else {
                        format!("toplevel_{:?}", std::mem::discriminant(item))
                    };
                    
                    visitor.symbols.push(Symbol {
                        name: format!("toplevel_item_{}", i),
                        symbol_type,
                        source_file: file_path.to_string(),
                        crate_name: crate_name.to_string(),
                        dependencies: vec![],
                    });
                }
            }
        }
        
        Ok(visitor.symbols)
    } else {
        // If parsing fails, still record the file
        Ok(vec![Symbol {
            name: format!("parse_failed_{}", file_path.split('/').last().unwrap_or("unknown")),
            symbol_type: "parse_error".to_string(),
            source_file: file_path.to_string(),
            crate_name: crate_name.to_string(),
            dependencies: vec![],
        }])
    }
}

// Use proven file discovery pattern from simple-split
pub fn find_rust_files_in_dependency_fast(dep_path: &str) -> Vec<std::path::PathBuf> {
    let path = std::path::Path::new(dep_path);
    if !path.exists() {
        return Vec::new();
    }
    
    WalkDir::new(path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| {
            let path = e.path();
            // Skip output directories like simple-split does
            if path.to_string_lossy().contains("output2") || 
               path.to_string_lossy().contains("enhanced_output") ||
               path.to_string_lossy().contains("target/") ||
               path.to_string_lossy().contains(".git/") {
                return false;
            }
            path.extension().map_or(false, |ext| ext == "rs")
        })
        .map(|e| e.path().to_path_buf())
        .collect()
}

fn analyze_function_body_ast(block: &syn::Block) -> String {
    let mut body_parts = Vec::new();
    
    for stmt in &block.stmts {
        match stmt {
            syn::Stmt::Local(_) => body_parts.push("let".to_string()),
            syn::Stmt::Item(item) => {
                match item {
                    syn::Item::Fn(f) => body_parts.push(format!("fn_{}", f.sig.ident)),
                    syn::Item::Struct(s) => body_parts.push(format!("struct_{}", s.ident)),
                    _ => body_parts.push("item".to_string()),
                }
            },
            syn::Stmt::Expr(expr, _) => {
                body_parts.push(analyze_expression_ast(expr));
            },
            syn::Stmt::Macro(mac) => {
                if let Some(last_seg) = mac.mac.path.segments.last() {
                    body_parts.push(format!("macro_{}", last_seg.ident));
                }
            },
        }
    }
    
    format!("{}stmts[{}]", block.stmts.len(), body_parts.join(","))
}

fn analyze_expression_ast(expr: &syn::Expr) -> String {
    match expr {
        syn::Expr::Call(call) => {
            if let syn::Expr::Path(path) = &*call.func {
                if let Some(last_seg) = path.path.segments.last() {
                    format!("call_{}", last_seg.ident)
                } else {
                    "call".to_string()
                }
            } else {
                "call".to_string()
            }
        },
        syn::Expr::MethodCall(method) => {
            format!("method_{}", method.method)
        },
        syn::Expr::Path(path) => {
            if let Some(last_seg) = path.path.segments.last() {
                format!("path_{}", last_seg.ident)
            } else {
                "path".to_string()
            }
        },
        syn::Expr::If(_) => "if".to_string(),
        syn::Expr::Match(_) => "match".to_string(),
        syn::Expr::Loop(_) => "loop".to_string(),
        syn::Expr::While(_) => "while".to_string(),
        syn::Expr::ForLoop(_) => "for".to_string(),
        syn::Expr::Return(_) => "return".to_string(),
        syn::Expr::Block(_) => "block".to_string(),
        syn::Expr::Macro(mac) => {
            if let Some(last_seg) = mac.mac.path.segments.last() {
                format!("macro_{}", last_seg.ident)
            } else {
                "macro".to_string()
            }
        },
        _ => "expr".to_string(),
    }
}

fn extract_function_dependencies_ast(func: &syn::ItemFn) -> Vec<String> {
    let mut deps = Vec::new();
    
    // Extract from function signature
    for input in &func.sig.inputs {
        if let syn::FnArg::Typed(pat_type) = input {
            deps.extend(extract_types_from_type(&pat_type.ty));
        }
    }
    
    // Extract from return type
    if let syn::ReturnType::Type(_, ty) = &func.sig.output {
        deps.extend(extract_types_from_type(ty));
    }
    
    // Extract from function body using visitor pattern
    let mut body_visitor = DependencyVisitor { 
        dependencies: Vec::new(),
        use_mappings: HashMap::new(),
    };
    body_visitor.visit_block(&func.block);
    deps.extend(body_visitor.dependencies);
    
    deps
}

struct DependencyVisitor {
    dependencies: Vec<String>,
    use_mappings: HashMap<String, String>, // short_name -> full_path
}

impl<'ast> Visit<'ast> for DependencyVisitor {
    fn visit_item_use(&mut self, use_item: &'ast syn::ItemUse) {
        self.extract_use_mappings(&use_item.tree, Vec::new());
        syn::visit::visit_item_use(self, use_item);
    }
    
    fn visit_path(&mut self, path: &'ast syn::Path) {
        let path_str = path.segments.iter()
            .map(|seg| seg.ident.to_string())
            .collect::<Vec<_>>()
            .join("::");
        
        // Try to resolve using use mappings first
        if path.segments.len() == 1 {
            let short_name = &path_str;
            if let Some(full_path) = self.use_mappings.get(short_name) {
                self.dependencies.push(full_path.clone());
            } else {
                self.dependencies.push(path_str);
            }
        } else if path.segments.len() > 1 {
            self.dependencies.push(path_str);
        }
        
        syn::visit::visit_path(self, path);
    }
}

impl DependencyVisitor {
    fn extract_use_mappings(&mut self, tree: &syn::UseTree, prefix: Vec<String>) {
        match tree {
            syn::UseTree::Path(path) => {
                let mut new_prefix = prefix;
                new_prefix.push(path.ident.to_string());
                self.extract_use_mappings(&path.tree, new_prefix);
            }
            syn::UseTree::Name(name) => {
                let mut full_path = prefix;
                full_path.push(name.ident.to_string());
                let short_name = name.ident.to_string();
                self.use_mappings.insert(short_name, full_path.join("::"));
            }
            syn::UseTree::Group(group) => {
                for item in &group.items {
                    self.extract_use_mappings(item, prefix.clone());
                }
            }
            _ => {}
        }
    }
}

pub fn analyze_and_display_function_body(block: &syn::Block, indent: &str) {
    for (i, stmt) in block.stmts.iter().enumerate() {
        match stmt {
            syn::Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    let init_str = analyze_expression_ast(&init.expr);
                    println!("{}{}. let binding = {}", indent, i+1, init_str);
                } else {
                    println!("{}{}. let declaration", indent, i+1);
                }
            },
            syn::Stmt::Item(item) => {
                match item {
                    syn::Item::Fn(f) => println!("{}{}. fn {} definition", indent, i+1, f.sig.ident),
                    syn::Item::Struct(s) => println!("{}{}. struct {} definition", indent, i+1, s.ident),
                    _ => println!("{}{}. item definition", indent, i+1),
                }
            },
            syn::Stmt::Expr(expr, has_semi) => {
                let expr_analysis = analyze_expression_ast(expr);
                let semi = if has_semi.is_some() { ";" } else { "" };
                println!("{}{}. expression: {}{}", indent, i+1, expr_analysis, semi);
            },
            syn::Stmt::Macro(mac) => {
                if let Some(last_seg) = mac.mac.path.segments.last() {
                    println!("{}{}. macro call: {}!", indent, i+1, last_seg.ident);
                } else {
                    println!("{}{}. macro call", indent, i+1);
                }
            },
        }
    }
}

pub fn resolve_qualified_dependency(dep: &str, all_symbols: &HashMap<String, Symbol>) -> Option<String> {
    // Direct match first
    if let Some(symbol) = all_symbols.get(dep) {
        return Some(format!("{}:{}", symbol.crate_name, symbol.source_file));
    }
    
    // Handle qualified paths like "env::var"
    if dep.contains("::") {
        let parts: Vec<&str> = dep.split("::").collect();
        if parts.len() == 2 {
            let module = parts[0];
            let function = parts[1];
            
            // Look for function in module - prioritize std library
            let mut candidates = Vec::new();
            
            for (name, symbol) in all_symbols {
                if name == function {
                    let from_module_file = symbol.source_file.ends_with(&format!("/{}.rs", module));
                    let from_module_dir = symbol.source_file.contains(&format!("/{}/", module));
                    
                    if from_module_file || from_module_dir {
                        candidates.push(symbol);
                    }
                }
            }
            
            // Prioritize std library symbols
            for candidate in &candidates {
                if candidate.crate_name == "std" {
                    return Some(format!("{}:{}", candidate.crate_name, candidate.source_file));
                }
            }
            
            // Fallback to first candidate
            if let Some(candidate) = candidates.first() {
                return Some(format!("{}:{}", candidate.crate_name, candidate.source_file));
            }
        }
    }
    
    None
}

fn extract_types_from_type(ty: &syn::Type) -> Vec<String> {
    let mut types = Vec::new();
    
    match ty {
        syn::Type::Path(type_path) => {
            let path_str = type_path.path.segments.iter()
                .map(|seg| seg.ident.to_string())
                .collect::<Vec<_>>()
                .join("::");
            if path_str.len() > 1 {
                types.push(path_str);
            }
        },
        syn::Type::Reference(type_ref) => {
            types.extend(extract_types_from_type(&type_ref.elem));
        },
        syn::Type::Tuple(type_tuple) => {
            for elem in &type_tuple.elems {
                types.extend(extract_types_from_type(elem));
            }
        },
        _ => {},
    }
    
    types
}

fn extract_struct_dependencies(s: &syn::ItemStruct) -> Vec<String> {
    let mut deps = Vec::new();
    
    for field in &s.fields {
        let type_str = field.ty.to_token_stream().to_string();
        deps.extend(extract_types_from_string(&type_str));
    }
    
    deps
}

fn extract_enum_dependencies(e: &syn::ItemEnum) -> Vec<String> {
    let mut deps = Vec::new();
    
    for variant in &e.variants {
        for field in &variant.fields {
            let type_str = field.ty.to_token_stream().to_string();
            deps.extend(extract_types_from_string(&type_str));
        }
    }
    
    deps
}

fn extract_trait_dependencies(t: &syn::ItemTrait) -> Vec<String> {
    let mut deps = Vec::new();
    let trait_str = t.to_token_stream().to_string();
    deps.extend(extract_types_from_string(&trait_str));
    deps
}

fn extract_impl_dependencies(i: &syn::ItemImpl) -> Vec<String> {
    let mut deps = Vec::new();
    let impl_str = i.to_token_stream().to_string();
    deps.extend(extract_types_from_string(&impl_str));
    deps
}

fn extract_const_dependencies(c: &syn::ItemConst) -> Vec<String> {
    let type_str = c.ty.to_token_stream().to_string();
    extract_types_from_string(&type_str)
}

fn extract_static_dependencies(s: &syn::ItemStatic) -> Vec<String> {
    let type_str = s.ty.to_token_stream().to_string();
    extract_types_from_string(&type_str)
}

fn extract_type_dependencies(t: &syn::ItemType) -> Vec<String> {
    let type_str = t.ty.to_token_stream().to_string();
    extract_types_from_string(&type_str)
}

fn extract_types_from_string(s: &str) -> Vec<String> {
    let mut types = Vec::new();
    
    for word in s.split_whitespace() {
        let clean = word.trim_matches(|c: char| !c.is_alphanumeric() && c != ':' && c != '_');
        if clean.contains("::") || (clean.len() > 1 && clean.chars().next().unwrap().is_uppercase()) {
            if clean != "::" && clean.len() > 2 {
                types.push(clean.to_string());
            }
        }
    }
    
    types
}

pub fn resolve_symbols_recursively_fast(
    main_symbols: Vec<String>,
    all_symbols: &HashMap<String, Symbol>,
    max_iterations: usize
) -> SymbolResolution {
    let mut resolved = HashMap::new();
    let mut resolution_order = Vec::new();
    let mut queue = VecDeque::new();
    let mut visited = HashSet::new();
    let mut iterations = 0;
    let mut max_depth = 0;
    
    // Start with main symbols
    for symbol in main_symbols {
        queue.push_back((symbol, 0));
    }
    
    while let Some((symbol_name, depth)) = queue.pop_front() {
        if iterations >= max_iterations {
            break;
        }
        
        if visited.contains(&symbol_name) {
            continue;
        }
        
        visited.insert(symbol_name.clone());
        max_depth = max_depth.max(depth);
        
        if let Some(symbol) = all_symbols.get(&symbol_name) {
            resolved.insert(symbol_name.clone(), symbol.clone());
            resolution_order.push(symbol_name.clone());
            
            // Add dependencies to queue
            for dep in &symbol.dependencies {
                if !visited.contains(dep) && dep.len() > 2 {
                    queue.push_back((dep.clone(), depth + 1));
                }
            }
        }
        
        iterations += 1;
        
        // Progress indicator for large resolutions
        if iterations % 1000 == 0 {
            println!("  🔄 Resolved {} symbols (depth {})", iterations, depth);
        }
    }
    
    SymbolResolution {
        main_routine: "main".to_string(),
        resolved_symbols: resolved,
        resolution_order,
        total_resolved: iterations,
        max_depth,
    }
}

#[macro_export]
macro_rules! mkfast_symbol_resolution {
    ($max_iterations:expr) => {{
        let rustc_deps = get_rustc_dependencies().unwrap_or_default();
        let mut all_symbols = HashMap::new();
        
        println!("🔍 Fast symbol extraction using proven syn patterns...");
        for dep in &rustc_deps {
            let rust_files = find_rust_files_in_dependency_fast(&dep.path);
            println!("  📦 {}: {} files", dep.name, rust_files.len());
            
            for file in rust_files {
                if let Ok(symbols) = extract_all_symbols_from_file_fast(&file.to_string_lossy(), &dep.name) {
                    for symbol in symbols {
                        // Debug: show env-related symbols
                        if symbol.source_file.contains("/env.rs") && symbol.name == "var" {
                            println!("    🔍 Found env::var: {} in {}", symbol.name, symbol.source_file);
                        }
                        
                        // NO OVERWRITING - Keep ALL symbols with unique names
                        if let Some(existing) = all_symbols.get(&symbol.name) {
                            // Generate hash for old symbol to make it unique
                            let mut hasher1 = std::collections::hash_map::DefaultHasher::new();
                            existing.source_file.hash(&mut hasher1);
                            let existing_hash = format!("{:x}", hasher1.finish() & 0xFFFF);
                            
                            let mut hasher2 = std::collections::hash_map::DefaultHasher::new();
                            symbol.source_file.hash(&mut hasher2);
                            let symbol_hash = format!("{:x}", hasher2.finish() & 0xFFFF);
                            
                            // Save existing with hash
                            let existing_unique = format!("{}_{}", existing.name, existing_hash);
                            all_symbols.insert(existing_unique, existing.clone());
                            
                            // Save new symbol with hash
                            let symbol_unique = format!("{}_{}", symbol.name, symbol_hash);
                            all_symbols.insert(symbol_unique, symbol.clone());
                            
                            // Also save both with module::name format
                            let existing_module = format!("{}::{}", existing.crate_name, existing.name);
                            let symbol_module = format!("{}::{}", symbol.crate_name, symbol.name);
                            
                            all_symbols.insert(existing_module, existing.clone());
                            all_symbols.insert(symbol_module, symbol.clone());
                            
                            println!("    ⚠️  Symbol conflict resolved: '{}'", symbol.name);
                            println!("        Saved as: {}_{} and {}::{}", existing.name, existing_hash, existing.crate_name, existing.name);
                            println!("        Saved as: {}_{} and {}::{}", symbol.name, symbol_hash, symbol.crate_name, symbol.name);
                            
                            // Keep original name pointing to std if available, otherwise first found
                            if symbol.crate_name == "std" {
                                all_symbols.insert(symbol.name.clone(), symbol);
                            } else if existing.crate_name != "std" {
                                all_symbols.insert(symbol.name.clone(), symbol);
                            }
                        } else {
                            // No conflict - save with module name too
                            let module_name = format!("{}::{}", symbol.crate_name, symbol.name);
                            all_symbols.insert(symbol.name.clone(), symbol.clone());
                            all_symbols.insert(module_name, symbol);
                        }
                    }
                }
            }
        }
        
        println!("✅ Extracted {} total symbols", all_symbols.len());
        
        // Start resolution from actual main functions found in the codebase
        let main_symbols: Vec<String> = all_symbols.keys()
            .filter(|name| name.as_str() == "main" || name.ends_with("::main"))
            .cloned()
            .collect();
        
        println!("🎯 MAIN FUNCTION AST ANALYSIS:");
        println!("  📊 Total symbols extracted: {}", all_symbols.len());
        println!("  🔍 Main functions found: {}", main_symbols.len());
        
        if main_symbols.is_empty() {
            println!("  ⚠️  No main functions discovered");
            let main_like: Vec<String> = all_symbols.keys()
                .filter(|name| name.to_lowercase().contains("main"))
                .cloned()
                .collect();
            println!("  🔍 Functions containing 'main': {}", main_like.len());
            for name in main_like.iter().take(5) {
                if let Some(symbol) = all_symbols.get(name) {
                    println!("    📋 {} [{}] from {}", name, symbol.symbol_type, symbol.source_file);
                    println!("       🔗 {} dependencies: {:?}", symbol.dependencies.len(), 
                             symbol.dependencies.iter().take(3).collect::<Vec<_>>());
                }
            }
        } else {
            println!("  📋 Main function AST details:");
            for name in &main_symbols {
                if let Some(symbol) = all_symbols.get(name) {
                    println!("    🎯 {} [{}] from {}", name, symbol.symbol_type, symbol.source_file);
                    println!("       🔗 Dependencies ({}): {:?}", symbol.dependencies.len(), 
                             symbol.dependencies.iter().take(5).collect::<Vec<_>>());
                    
                    // Show detailed AST body content
                    if let Ok(content) = std::fs::read_to_string(&symbol.source_file) {
                        if let Ok(parsed) = syn::parse_file(&content) {
                            for item in &parsed.items {
                                if let syn::Item::Fn(func) = item {
                                    if func.sig.ident == name {
                                        println!("       📝 AST Body Analysis:");
                                        analyze_and_display_function_body(&func.block, "         ");
                                        
                                        // Check resolution status of each dependency
                                        println!("       🔍 Dependency Resolution Status:");
                                        for (i, dep) in symbol.dependencies.iter().take(10).enumerate() {
                                            let resolved = resolve_qualified_dependency(dep, &all_symbols);
                                            let status = if resolved.is_some() { "✅" } else { "❌" };
                                            let location = if let Some(loc) = resolved {
                                                format!(" -> {}", loc)
                                            } else {
                                                "".to_string()
                                            };
                                            println!("         {}. {} {}{}", i+1, status, dep, location);
                                        }
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        
        println!("🎯 MAIN SYMBOL DISCOVERY:");
        println!("  📊 Total symbols extracted: {}", all_symbols.len());
        println!("  🔍 Main symbols found: {}", main_symbols.len());
        
        if main_symbols.is_empty() {
            println!("  ⚠️  No main symbols discovered in codebase");
            println!("  🔍 Searching for any function containing 'main'...");
            let main_like: Vec<String> = all_symbols.keys()
                .filter(|name| name.to_lowercase().contains("main"))
                .cloned()
                .collect();
            println!("  📋 Functions containing 'main': {}", main_like.len());
            for (i, name) in main_like.iter().take(10).enumerate() {
                if let Some(symbol) = all_symbols.get(name) {
                    println!("    {}. {} ({}:{})", i+1, name, symbol.source_file, symbol.symbol_type);
                }
            }
        } else {
            println!("  📋 Main symbols discovered:");
            for (i, name) in main_symbols.iter().enumerate() {
                if let Some(symbol) = all_symbols.get(name) {
                    println!("    {}. {} ({}:{})", i+1, name, symbol.source_file, symbol.symbol_type);
                    println!("       Dependencies: {}", symbol.dependencies.len());
                }
            }
        }
        
        let resolution = resolve_symbols_recursively_fast(main_symbols, &all_symbols, $max_iterations);
        
        println!("🎯 FAST RECURSIVE SYMBOL RESOLUTION:");
        println!("  📊 Target iterations: {}", $max_iterations);
        println!("  🔧 Symbols resolved: {}", resolution.total_resolved);
        println!("  📈 Max depth reached: {}", resolution.max_depth);
        println!("  🌳 Resolution tree size: {}", resolution.resolved_symbols.len());
        
        resolution
    }};
}

#[macro_export]
macro_rules! mk12k_symbol_resolution {
    () => {{
        mkfast_symbol_resolution!(12000)
    }};
}
